(()=>{'use strict';const root=document.querySelector('#workbench'),scene=root.querySelector('.bench-scene'),drawer=root.querySelector('#benchDrawer'),reduce=matchMedia('(prefers-reduced-motion: reduce)');
const areas=[
{id:'genetics',name:'Genetics & cells',tag:'THE INSTRUCTIONS FOR LIFE',copy:'Explore DNA, cell division and inheritance.',x:100,y:0,topics:[['genetics','Genetics & cell division']]},
{id:'evolution',name:'Evolution',tag:'CHANGE ACROSS GENERATIONS',copy:'Explore variation, selection and the origin of species.',x:0,y:100,topics:[['evolution','Evolution & natural selection']]},
{id:'rates',name:'Reaction rates',tag:'PARTICLES IN MOTION',copy:'Investigate kinetic theory and what changes the pace of a reaction.',x:50,y:100,topics:[['rates','Reaction rates']]},
{id:'heat',name:'Heat transfer',tag:'FOLLOW THE ENERGY',copy:'See conduction, convection and radiation in action.',x:50,y:100,topics:[['heat','Heat transfer']]}
];
scene.innerHTML=areas.map((a,i)=>`<button class="bench-exhibit" data-area="${a.id}" aria-expanded="false" aria-controls="benchDrawer" style="--x:${a.x}%;--y:${a.y}%;--delay:${i*.7}s"><span class="bench-art" aria-hidden="true"></span>${a.id==='heat'?'<span class="heat-exhibit" aria-hidden="true"><span class="heat-vessel"><i></i><i></i><i></i><i></i><i></i></span><span class="heat-base"></span></span>':''}<span class="bench-aura" aria-hidden="true"></span><span class="bench-mote m1" aria-hidden="true"></span><span class="bench-mote m2" aria-hidden="true"></span><span class="bench-label"><span class="bench-num">0${i+1} / EXPLORE</span><strong>${a.name}<span aria-hidden="true">↗</span></strong></span></button>`).join('');
let motion=!reduce.matches;try{if(localStorage.getItem('science-studio-workbench-motion')==='off')motion=false;}catch(e){}
const motionButton=root.querySelector('#benchMotion');function syncMotion(){root.classList.toggle('bench-still',!motion||reduce.matches);document.body.classList.toggle('decor-still',!motion||reduce.matches);motionButton.setAttribute('aria-pressed',String(motion&&!reduce.matches));motionButton.textContent=motion&&!reduce.matches?'Animation on ◉':'Animation off ○';}syncMotion();motionButton.onclick=()=>{motion=!(motion&&!reduce.matches);try{localStorage.setItem('science-studio-workbench-motion',motion?'on':'off')}catch(e){}syncMotion()};reduce.addEventListener('change',syncMotion);
function choose(id){const a=areas.find(a=>a.id===id);scene.querySelectorAll('button').forEach(b=>b.setAttribute('aria-expanded',String(b.dataset.area===id)));drawer.hidden=false;drawer.innerHTML=`<div class="bench-drawer-heading"><div><p class="eyebrow">${a.tag}</p><h3 id="benchAreaHeading" tabindex="-1">${a.name}</h3><p>${a.copy}</p></div><button id="benchClose" aria-label="Close topic drawer">✕</button></div><div class="bench-routes">${a.topics.map(([id,title])=>`<div><h4>${title}</h4><button data-bench-model="${id}">Explore animation <span aria-hidden="true">↗</span></button><button data-watch-topic="${id}">Watch &amp; learn ↗</button>${id==='genetics'||id==='rates'?`<a class="bench-extra" href="#objectiveLabs" data-objective-jump="${id==='rates'?'collision':'dna'}">${id==='rates'?'Explore collision theory':'Build a DNA strand'} ↗</a>`:''}<button data-bench-quiz="${id}">Practise questions <span aria-hidden="true">→</span></button></div>`).join('')}</div><div class="bench-study-links"><a href="#mockExams">Take a timed mock →</a><a href="#revisionPlan">My revision plan →</a><span>Illustrative exhibits · open the models to investigate the science.</span></div>`;drawer.querySelector('#benchClose').onclick=close;drawer.querySelectorAll('[data-bench-model]').forEach(b=>b.onclick=()=>window.dispatchEvent(new CustomEvent('science-model-topic',{detail:b.dataset.benchModel})));drawer.querySelectorAll('[data-bench-quiz]').forEach(b=>b.onclick=()=>window.dispatchEvent(new CustomEvent('science-exam-topic',{detail:b.dataset.benchQuiz})));drawer.querySelector('h3').focus({preventScroll:true});drawer.scrollIntoView({behavior:motion&&!reduce.matches?'smooth':'auto',block:'nearest'});}
function close(){const selected=scene.querySelector('[aria-expanded="true"]');drawer.hidden=true;selected?.setAttribute('aria-expanded','false');selected?.focus({preventScroll:true});}scene.querySelectorAll('button').forEach(b=>{b.onclick=()=>choose(b.dataset.area);b.onpointermove=e=>{if(!motion||reduce.matches||e.pointerType!=='mouse')return;const r=b.getBoundingClientRect();b.style.setProperty('--tilt-x',`${(e.clientY-r.top-r.height/2)/r.height*-5}deg`);b.style.setProperty('--tilt-y',`${(e.clientX-r.left-r.width/2)/r.width*5}deg`);};b.onpointerleave=()=>{b.style.removeProperty('--tilt-x');b.style.removeProperty('--tilt-y');};});root.addEventListener('keydown',e=>{if(e.key==='Escape'&&!drawer.hidden)close()});
})();
